function nextCode(collection, field, prefix){const xs=Array.isArray(db[collection])?db[collection]:[];let max=0;for(const x of xs){const m=String(x?.[field]||'').match(new RegExp(`^${prefix}-(\\d+)$`));if(m)max=Math.max(max,Number(m[1]));}return `${prefix}-${String(max+1).padStart(6,'0')}`}
function publicToken(){return crypto.randomBytes(18).toString('base64url')}
function ensurePublicTokens(){for(const a of db.assets||[]){if(!a.publicToken)a.publicToken=publicToken()}}
function migrateReceiptSnapshots(){for(const r of db.receipts||[]){if(!r.data&&!r.asset)continue;const a=db.assets.find(x=>x.id===r.assetId);if(a&&r.type==='ASSET_ENTRY'&&r.data){r.data.publicToken=a.publicToken;r.data.papersStatus=r.data.papersStatus||a.customFields?.papersStatus||'';r.data.papersNotes=r.data.papersNotes||a.customFields?.papersNotes||''}}}

function migrateHumanCodes(){
  const byCreated=(a,b)=>new Date(a.createdAt||0)-new Date(b.createdAt||0);
  for(const [collection,field,prefix] of [['assets','code','AST'],['reservations','code','RES'],['offers','code','OFF'],['orders','code','ORD'],['contracts','code','CNT'],['invoices','number','INV']]){
    let n=0; const xs=(db[collection]||[]).slice().sort(byCreated); const re=new RegExp(`^${prefix}-(\\d{6})$`);
    for(const x of xs){const m=String(x?.[field]||'').match(re); if(m)n=Math.max(n,Number(m[1]));}
    for(const x of xs){if(!re.test(String(x?.[field]||'')))x[field]=`${prefix}-${String(++n).padStart(6,'0')}`;}
  }
  let entryN=0,payN=0; const receipts=(db.receipts||[]).slice().sort(byCreated);
  for(const r of receipts){if(r.type==='ASSET_ENTRY'){const m=String(r.number||'').match(/^REC-(\\d{6})$/);if(m)entryN=Math.max(entryN,Number(m[1]));}else if(r.type==='PAYMENT'){const m=String(r.number||'').match(/^PAY-(\\d{6})$/);if(m)payN=Math.max(payN,Number(m[1]));}}
  for(const r of receipts){if(r.type==='ASSET_ENTRY'&&!/^REC-\\d{6}$/.test(String(r.number||'')))r.number=`REC-${String(++entryN).padStart(6,'0')}`;if(r.type==='PAYMENT'&&!/^PAY-\\d{6}$/.test(String(r.number||'')))r.number=`PAY-${String(++payN).padStart(6,'0')}`;}
}
